from django.db import migrations, models


def preencher_baixados(apps, schema_editor):
    """Recupera a data de baixa dos logs antigos 'Baixa realizada'."""
    OficioRecord = apps.get_model('projudi', 'OficioRecord')
    OficioLog = apps.get_model('projudi', 'OficioLog')

    datas = {}
    logs = OficioLog.objects.filter(
        mensagem__icontains='Baixa realizada'
    ).exclude(oficio_id=None).order_by('oficio_id', '-created_at')

    for log in logs:
        datas.setdefault(log.oficio_id, log.created_at)

    for record in OficioRecord.objects.filter(baixado_em__isnull=True):
        data = datas.get(record.pk)
        if data:
            record.baixado_em = data
            record.save(update_fields=['baixado_em'])


